const monsterData=[
['🍄','포자 버섯',1,12,8],['🐌','이끼 달팽이',1,14,9],['🐛','풀잎 애벌레',2,16,10],['🐿️','도토리 다람쥐',2,18,11],['🐸','연못 개구리',3,20,12],['🦋','달빛 나비',3,22,13],['🦔','가시 고슴도치',4,25,15],['🐝','꿀벌 정찰병',5,28,16],['🦇','밤그늘 박쥐',6,32,18],['🐺','숲 늑대',8,38,21],['🕷️','거미 여왕의 자식',10,45,24],['🧚','장난꾸러기 요정',12,50,27],['🦊','붉은여우',14,56,30],['🐗','숲 멧돼지',16,64,33],['🪨','바위 골렘',18,75,37],['👻','떠도는 정령',20,78,40],['🦉','고대 부엉이',22,82,43],['🐍','푸른 독사',24,90,46],['🐻','달곰',26,98,50],['🌳','움직이는 고목',28,110,54],
['🦂','모래 전갈',32,125,62],['🐫','사막 방랑자',35,135,66],['🧞','램프 정령',38,150,71],['🦅','황금 독수리',41,164,76],['🐊','늪지 악어',44,175,82],['🧟','오래된 수호병',47,190,88],['🦎','용암 도마뱀',50,210,96],['🔥','불꽃 정령',53,230,102],['🧌','산맥 트롤',56,248,110],['🐉','새끼 와이번',59,270,120],['🧛','핏빛 사냥꾼',62,295,130],['🦇','수정 박쥐',65,320,140],['🪼','심해 유령해파리',68,350,152],['🦈','검은바다 상어',71,380,165],['🐙','심연의 촉수괴물',74,410,178],['🧜','노래하는 마녀',77,445,192],['🐚','산호 갑주괴물',80,480,206],['🧊','서리 망령',84,520,224],['🐧','빙하의 전사',88,560,240],['🐻‍❄️','눈보라 곰',92,610,260],
['🪐','별먼지 미믹',98,680,285],['👽','성운 침략자',104,760,310],['🤖','고대 기계병',110,850,340],['🛸','공허 추적자',116,950,375],['🦄','타락한 유니콘',122,1060,410],['🦁','태양 사자',128,1190,450],['🐲','황혼의 용',134,1330,500],['👹','지옥 문지기',140,1490,550],['👿','혼돈의 악마',146,1670,610],['🐲','고룡 아르카',150,1900,680],['🌑','그림자 포식자',155,2200,760],['🧿','천공의 눈',160,2500,850],['⚡','번개의 거신',165,2850,960],['🪽','타락한 천사',170,3250,1080],['💀','망각의 군주',175,3700,1220],['🌋','종말의 화신',180,4200,1400],['🐉','성운 폭군',185,4800,1600],['👾','차원의 포식자',190,5500,1850],['🌌','별의 파괴자',195,6400,2150],['✨','빛의 공허왕',200,8000,2600]
];
const zones=['달빛 숲','모래시계 사막','잿빛 산맥','심해의 균열','얼음 왕관','별의 경계'];
const zoneIndex=l=>l<30?0:l<60?1:l<90?2:l<120?3:l<150?4:5;
const zoneIcons=['🌲','🏜️','⛰️','🌊','❄️','🌌'];
const state={level:1,xp:0,gold:0,kills:0,hp:100,maxHp:100,mp:60,maxMp:60,potions:3,dust:0,player:{x:.5,y:.55},monsters:[],seen:new Set(),job:'초보 모험가',firstJob:'',secondJob:'',moving:{},attackTimer:0,spawnTimer:0,damageFlash:0,paused:false};
const $=id=>document.getElementById(id);const canvas=$('world'),ctx=canvas.getContext('2d');let W=0,H=0,dpr=1,last=0,toastTimer;
function expNeed(l){return Math.floor(28+l*4.6)}
function getZone(){return zones[zoneIndex(state.level)]}
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawMap()}
window.addEventListener('resize',resize);
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function stats(){state.maxHp=100+state.level*12;state.maxMp=60+state.level*4;state.hp=Math.min(state.maxHp,state.hp);state.mp=Math.min(state.maxMp,state.mp)}
function refresh(){stats();const l=state.level,need=expNeed(l),p=state.xp/need*100;$('levelTop').textContent='Lv. '+l;$('mobileLevel').textContent=l;$('goldTop').textContent='◈ '+state.gold.toLocaleString();$('killTop').textContent=state.kills.toLocaleString();$('levelLabel').textContent=`LV. ${l} / 200`;$('xpBar').style.width=p+'%';$('xpLabel').textContent=`${state.xp} / ${need} EXP`;$('hpText').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('hpBar').style.width=state.hp/state.maxHp*100+'%';$('mpText').textContent=`${Math.ceil(state.mp)} / ${state.maxMp}`;$('mpBar').style.width=state.mp/state.maxMp*100+'%';$('goldBag').textContent=state.gold.toLocaleString();$('dustBag').textContent=state.dust;$('potionBag').textContent=state.potions;$('potionCount').textContent=state.potions;$('mobilePotionCount').textContent=state.potions;$('mobileHp').textContent='HP '+Math.round(state.hp/state.maxHp*100)+'%';$('heroName').textContent=state.level>=50?'별빛의 '+(state.secondJob||state.firstJob||'모험가'):'새벽의 모험가';$('jobName').textContent=state.job;const q=Math.min(5,state.kills);$('questProgress').textContent=`처치 ${q} / 5`;if(state.kills>=5)$('questTitle').textContent='숲의 첫 수호자';$('codexCount').textContent=`${state.seen.size} / 60`;drawMap();renderEnemies()}
function makeMonster(){const zi=zoneIndex(state.level),range=monsterData.filter(m=>Math.floor((m[2]-1)/30)===zi);const choice=range[Math.floor(Math.random()*range.length)]||monsterData[Math.min(59,Math.floor(Math.random()*10))];const lvl=Math.max(1,Math.min(200,choice[2]+Math.floor(Math.random()*5)));return {data:choice,lvl,x:.12+Math.random()*.76,y:.15+Math.random()*.73,hp:choice[3]*(1+(lvl-choice[2])*.035),maxHp:choice[3]*(1+(lvl-choice[2])*.035),cool:Math.random()*2,hit:0}}
function ensureMonsters(){while(state.monsters.length<9)state.monsters.push(makeMonster())}
function renderEnemies(){const list=$('enemyList');if(!list)return;const seen=[...state.seen].slice(-5).reverse();list.innerHTML=(seen.length?seen:monsterData.slice(0,4).map(m=>m[1])).map(name=>{const m=monsterData.find(a=>a[1]===name);return `<div class="enemy"><span class="ico">${m?.[0]||'❔'}</span><div><b>${name}</b><small>경험치 +${m?.[4]||10}</small></div><span class="lvl">Lv.${m?.[2]||1}</span></div>`}).join('');$('nearCount').textContent=`${state.seen.size}종 발견`}
function addXP(n){if(state.level>=200)return;state.xp+=n;while(state.xp>=expNeed(state.level)&&state.level<200){state.xp-=expNeed(state.level);state.level++;state.hp=100+state.level*12;state.mp=60+state.level*4;toast(`레벨 업! Lv.${state.level} ✨`);if(state.level===50||state.level===150){setTimeout(()=>promotion(state.level===50?1:2),450)}}if(state.level===200)state.xp=0;refresh()}
function promotion(stage){const choices=stage===1?[['🛡️','수호기사','방어와 생명력이 강한 기사'],['🏹','별궁수','빠르고 정확한 원거리 사냥꾼'],['🔮','성운술사','강력한 마법과 별빛 기술']]:[['⚔️','성검군주','빛을 가르는 전설의 검'],['🌠','천공추적자','유성과 함께하는 명사수'],['✨','대마도사','성운을 다루는 마법의 정점']];$('modal').innerHTML=`<div class="eyebrow">${stage===1?'LEVEL 50 · 1차 전직':'LEVEL 150 · 2차 전직'}</div><h2>${stage===1?'새로운 길을 선택하세요':'전설의 문이 열렸어요'}</h2><p>전직은 모험가의 운명을 바꿉니다. 마음에 드는 직업을 선택해 주세요.</p>${choices.map(c=>`<button class="choice" data-job="${c[1]}"><b>${c[0]} ${c[1]}</b><br><span style="font-size:11px;color:#a8a9a8">${c[2]}</span></button>`).join('')}`;$('modalWrap').classList.add('open');$('modal').querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{state.job=b.dataset.job;if(stage===1)state.firstJob=b.dataset.job;else state.secondJob=b.dataset.job;state.hp=state.maxHp;state.mp=state.maxMp;$('modalWrap').classList.remove('open');toast(`${state.job}로 전직했습니다!`);refresh()})}
function strike(){if(state.paused)return;state.attackTimer=.22;let candidates=state.monsters.map((m,i)=>({m,i,d:Math.hypot((m.x-state.player.x)*W,(m.y-state.player.y)*H)})).filter(a=>a.d<Math.min(190,W*.4)).sort((a,b)=>a.d-b.d);if(!candidates.length){toast('몬스터가 가까이 없어요. 방향키로 다가가세요!');return}const {m,i}=candidates[0],base=18+state.level*3.2+(state.firstJob?35:0)+(state.secondJob?100:0),dmg=base*(.8+Math.random()*.5);m.hp-=dmg;m.hit=.24;state.mp=Math.min(state.maxMp,state.mp+2);if(m.hp<=0){const data=m.data;state.kills++;state.gold+=Math.floor(data[4]*(.6+Math.random()*.8));state.dust+=Math.random()<.16?1:0;state.seen.add(data[1]);addXP(data[4]);state.monsters.splice(i,1);if(state.kills===5){state.gold+=100;state.potions++;toast('퀘스트 완료! +100 골드 · 물약 +1')}refresh()}else refresh()}
function heal(){if(state.mp<12){toast('마나가 부족해요!');return}if(state.hp>=state.maxHp){toast('생명력이 이미 가득해요');return}state.mp-=12;state.hp=Math.min(state.maxHp,state.hp+state.maxHp*.32);refresh();toast('회복의 빛! 생명력 회복')}
function potion(){if(state.potions<=0){toast('물약이 없어요! 몬스터를 처치해 찾아보세요.');return}state.potions--;state.hp=Math.min(state.maxHp,state.hp+state.maxHp*.55);refresh();toast('회복 물약을 사용했어요')}
$('attackBtn').onclick=strike;$('mobileAttack').onclick=strike;$('healBtn').onclick=heal;$('potionBtn').onclick=potion;$('mobilePotion').onclick=potion;
const directions={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};window.addEventListener('keydown',e=>{if(directions[e.key]){state.moving[directions[e.key]]=true;e.preventDefault()}if(e.code==='Space'){strike();e.preventDefault()}if(e.key==='q'||e.key==='Q')strike();if(e.key==='e'||e.key==='E')heal();if(e.key==='r'||e.key==='R')potion()});window.addEventListener('keyup',e=>{if(directions[e.key])state.moving[directions[e.key]]=false});document.querySelectorAll('.pad').forEach(b=>{const dir=b.dataset.dir;const on=e=>{e.preventDefault();state.moving[dir]=true;b.setPointerCapture?.(e.pointerId)};const off=e=>{e.preventDefault();state.moving[dir]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('lostpointercapture',off)});

function drawMap(){const mc=$('minimap');if(!mc)return;const r=mc.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);if(!r.width||!r.height)return;mc.width=r.width*d;mc.height=r.height*d;const c=mc.getContext('2d');c.scale(d,d);c.fillStyle='#192623';c.fillRect(0,0,r.width,r.height);for(let i=0;i<27;i++){let x=(i*67%r.width),y=(i*43%r.height);c.fillStyle=i%2?'#34483a':'#41533e';c.beginPath();c.arc(x,y,5+i%8,0,Math.PI*2);c.fill()}c.fillStyle='#f2d47d';c.beginPath();c.arc(state.player.x*r.width,state.player.y*r.height,4,0,Math.PI*2);c.fill();state.monsters.forEach(m=>{c.fillStyle='#e99c78';c.fillRect(m.x*r.width-1,m.y*r.height-1,3,3)})}
function background(){const zone=zoneIndex(state.level),palette=[['#314b40','#51644b','#b8bd80'],['#8d6743','#c29356','#f3d288'],['#384447','#63685c','#c3c0a3'],['#204650','#34717a','#a7d1bd'],['#465767','#8ca3a9','#d6e8df'],['#202e4c','#586497','#d2a9fa']][zone];const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,palette[0]);grad.addColorStop(.58,palette[1]);grad.addColorStop(1,palette[2]);ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);const time=performance.now()/1000;ctx.globalAlpha=.16;for(let i=0;i<28;i++){const x=(i*173+Math.sin(time*.25+i)*15)%W,y=(i*97+time*(8+i%6))%(H+20);ctx.fillStyle=i%3?'#fbf3bd':'#c6f5f2';ctx.beginPath();ctx.arc(x,y,1+i%3*.45,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// distant silhouette
ctx.fillStyle='#17282acc';ctx.beginPath();ctx.moveTo(0,H*.57);for(let x=0;x<=W;x+=30)ctx.lineTo(x,H*(.47+Math.sin(x*.012+zone)*.055+Math.sin(x*.03)*.02));ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
if(zone===0){for(let i=0;i<14;i++){const x=(i*137+34)%W,y=H*(.4+(i*37%40)/100),s=H*(.14+(i%3)*.035);ctx.fillStyle=i%2?'#203b32':'#294638';ctx.fillRect(x-4,y,s*.08,H-y);ctx.fillStyle=i%2?'#1e4537':'#31543e';ctx.beginPath();ctx.arc(x,y,s*.55,0,Math.PI*2);ctx.arc(x-s*.27,y+s*.12,s*.37,0,Math.PI*2);ctx.arc(x+s*.29,y+s*.1,s*.38,0,Math.PI*2);ctx.fill()}}
else {for(let i=0;i<9;i++){let x=(i*191+20)%W,y=H*(.55+(i%4)*.08);ctx.fillStyle=zone===1?'#74563d':zone===4?'#dce8df55':'#273244';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+40+(i%3)*20,y-H*(.25+(i%4)*.06));ctx.lineTo(x+85,y);ctx.fill()}}
// glowing trail and ground tufts
ctx.strokeStyle=zone===0?'#d5c9833d':'#d7e5d333';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(W*.1,H*.78);ctx.bezierCurveTo(W*.3,H*.67,W*.63,H*.8,W*.92,H*.62);ctx.stroke();for(let i=0;i<24;i++){let x=(i*89+12)%W,y=H*(.72+(i%5)*.045);ctx.fillStyle=zone===0?'#aab77766':'#e0d3a855';ctx.fillRect(x,y,2,7)} }
function drawCharacter(x,y,hero=false,monster=null){ctx.save();ctx.translate(x,y);if(hero){ctx.fillStyle='#10131c66';ctx.beginPath();ctx.ellipse(0,15,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#394e73';ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-7,12);ctx.lineTo(7,12);ctx.lineTo(10,0);ctx.fill();ctx.fillStyle='#f1c99b';ctx.beginPath();ctx.arc(0,-8,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9dfed';ctx.beginPath();ctx.arc(0,-11,7,Math.PI,0);ctx.lineTo(7,-8);ctx.lineTo(-7,-8);ctx.fill();ctx.strokeStyle='#e8cc7f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,-1);ctx.lineTo(15,-13);ctx.stroke();ctx.fillStyle='#fff0b4';ctx.beginPath();ctx.arc(15,-13,2.4,0,Math.PI*2);ctx.fill()}else{const size=Math.min(19,12+monster.lvl*.035);ctx.fillStyle='#11151d77';ctx.beginPath();ctx.ellipse(0,size*.65,size*.76,size*.27,0,0,Math.PI*2);ctx.fill();ctx.font=`${size*1.7}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(monster.data[0],0,0);if(monster.hit>0){ctx.strokeStyle='#fff3c2';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,size,0,Math.PI*2);ctx.stroke()}const bw=Math.max(24,size*2.2);ctx.fillStyle='#1b1720';ctx.fillRect(-bw/2,-size-9,bw,3);ctx.fillStyle='#e86f69';ctx.fillRect(-bw/2,-size-9,bw*Math.max(0,monster.hp/monster.maxHp),3);if(monster.lvl>=50){ctx.font='9px Arial';ctx.fillStyle='#f5daa0';ctx.fillText('Lv.'+monster.lvl,0,-size-14)}}ctx.restore()}
function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;if(!state.paused){const v=dt*.34;let dx=(state.moving.right?1:0)-(state.moving.left?1:0),dy=(state.moving.down?1:0)-(state.moving.up?1:0);if(dx||dy){const z=Math.hypot(dx,dy);state.player.x=Math.max(.045,Math.min(.955,state.player.x+dx/z*v));state.player.y=Math.max(.1,Math.min(.93,state.player.y+dy/z*v))}state.attackTimer=Math.max(0,state.attackTimer-dt);state.spawnTimer+=dt;if(state.spawnTimer>3){state.spawnTimer=0;if(state.monsters.length<9)state.monsters.push(makeMonster())}state.monsters.forEach(m=>{m.cool-=dt;m.hit=Math.max(0,m.hit-dt);const d=Math.hypot((m.x-state.player.x)*W,(m.y-state.player.y)*H);if(d>52&&d<200){m.x+=(state.player.x-m.x)*dt*.025;m.y+=(state.player.y-m.y)*dt*.025}if(d<43&&m.cool<=0){m.cool=1.8+Math.random();state.hp=Math.max(0,state.hp-(3+Math.floor(m.lvl*.12)));state.damageFlash=.2;if(state.hp<=0){state.hp=state.maxHp*.55;state.gold=Math.max(0,state.gold-10);state.player.x=.5;state.player.y=.55;toast('기절했어요. 마을에서 다시 일어납니다. -10 골드')}refresh()}});state.damageFlash=Math.max(0,state.damageFlash-dt)}if(W&&H){background();const sort=[...state.monsters.map(m=>({y:m.y,draw:()=>drawCharacter(m.x*W,m.y*H,false,m)})),{y:state.player.y,draw:()=>drawCharacter(state.player.x*W,state.player.y*H,true)}].sort((a,b)=>a.y-b.y);sort.forEach(a=>a.draw());if(state.damageFlash){ctx.fillStyle=`rgba(235,65,68,${state.damageFlash*.45})`;ctx.fillRect(0,0,W,H)}if(state.attackTimer){ctx.strokeStyle='#ffe697';ctx.lineWidth=3;ctx.beginPath();ctx.arc(state.player.x*W,state.player.y*H-2,30+(1-state.attackTimer/.22)*28,-1.2,1.3);ctx.stroke()}}requestAnimationFrame(frame)}
$('menuBtn').onclick=()=>{$('modal').innerHTML='<div class="eyebrow">별빛 원정대</div><h2>모험 메뉴</h2><p>현재 진행 상황은 이 기기에 자동 저장됩니다.</p><div class="modalactions"><button class="action secondary" id="saveBtn">💾 저장</button><button class="action secondary" id="closeMenu">닫기</button><button class="action" id="resetBtn">새 모험</button></div>';$('modalWrap').classList.add('open');$('closeMenu').onclick=()=>$('modalWrap').classList.remove('open');$('saveBtn').onclick=()=>{save();toast('모험을 저장했어요');$('modalWrap').classList.remove('open')};$('resetBtn').onclick=()=>{if(confirm('모든 진행 상황을 초기화할까요?')){localStorage.removeItem('starlight-rpg');location.reload()}}};$('soundBtn').onclick=()=>toast('별빛 숲의 소리를 듣고 있어요 ♫');$('modalWrap').onclick=e=>{if(e.target===$('modalWrap'))$('modalWrap').classList.remove('open')};
function save(){try{localStorage.setItem('starlight-rpg',JSON.stringify({...state,seen:[...state.seen],monsters:[]}))}catch(e){}}
function load(){try{const d=JSON.parse(localStorage.getItem('starlight-rpg'));if(d){Object.assign(state,d);state.seen=new Set(d.seen||[]);state.monsters=[];state.moving={}}}catch(e){}}
setInterval(save,8000);window.addEventListener('beforeunload',save);load();ensureMonsters();refresh();resize();requestAnimationFrame(frame);
</script>
</body></html>

