['🦂','모래 전갈',32,125,62],['🐫','사막 방랑자',35,135,66],['🧞','램프 정령',38,150,71],['🦅','황금 독수리',41,164,76],['🐊','늪지 악어',44,175,82],['🧟','오래된 수호병',47,190,88],['🦎','용암 도마뱀',50,210,96],['🔥','불꽃 정령',53,230,102],['🧌','산맥 트롤',56,248,110],['🐉','새끼 와이번',59,270,120],['🧛','핏빛 사냥꾼',62,295,130],['🦇','수정 박쥐',65,320,140],['🪼','심해 유령해파리',68,350,152],['🦈','검은바다 상어',71,380,165],['🐙','심연의 촉수괴물',74,410,178],['🧜','노래하는 마녀',77,445,192],['🐚','산호 갑주괴물',80,480,206],['🧊','서리 망령',84,520,224],['🐧','빙하의 전사',88,560,240],['🐻‍❄️','눈보라 곰',92,610,260],
['🪐','별먼지 미믹',98,680,285],['👽','성운 침략자',104,760,310],['🤖','고대 기계병',110,850,340],['🛸','공허 추적자',116,950,375],['🦄','타락한 유니콘',122,1060,410],['🦁','태양 사자',128,1190,450],['🐲','황혼의 용',134,1330,500],['👹','지옥 문지기',140,1490,550],['👿','혼돈의 악마',146,1670,610],['🐲','고룡 아르카',150,1900,680],['🌑','그림자 포식자',155,2200,760],['🧿','천공의 눈',160,2500,850],['⚡','번개의 거신',165,2850,960],['🪽','타락한 천사',170,3250,1080],['💀','망각의 군주',175,3700,1220],['🌋','종말의 화신',180,4200,1400],['🐉','성운 폭군',185,4800,1600],['👾','차원의 포식자',190,5500,1850],['🌌','별의 파괴자',195,6400,2150],['✨','빛의 공허왕',200,8000,2600]];
const zones=['달빛 숲','모래시계 사막','잿빛 산맥','심해의 균열','얼음 왕관','별의 경계'],zoneIcons=['🌲','🏜️','⛰️','🌊','❄️','🌌'];const zoneIndex=l=>l<30?0:l<60?1:l<90?2:l<120?3:l<150?4:5;
const state={level:1,xp:0,gold:0,kills:0,hp:100,maxHp:100,mp:60,maxMp:60,potions:3,dust:0,player:{x:.5,y:.55},monsters:[],seen:new Set(),job:'초보 모험가',firstJob:'',secondJob:'',moving:{},attackTimer:0,spawnTimer:0,damageFlash:0,paused:false};
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d');let W=0,H=0,dpr=1,last=0,toastTimer;
function expNeed(l){return Math.floor(28+l*4.6)}function getZone(){return zones[zoneIndex(state.level)]}
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawMap()};window.addEventListener('resize',resize);
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function stats(){state.maxHp=100+state.level*12;state.maxMp=60+state.level*4;state.hp=Math.min(state.maxHp,state.hp)}
function refresh(){stats();const l=state.level,need=expNeed(l),p=state.xp/need*100;$('levelTop').textContent='Lv. '+l;$('mobileLevel').textContent=l;$('goldTop').textContent='◈ '+state.gold.toLocaleString();$('killTop').textContent=state.kills.toLocaleString();$('levelLabel').textContent=`LV. ${l} / 200`;$('xpBar').style.width=p+'%';$('xpLabel').textContent=`${state.xp} / ${need} EXP`;$('hpText').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('hpBar').style.width=state.hp/state.maxHp*100+'%';$('mpText').textContent=`${Math.ceil(state.mp)} / ${state.maxMp}`;$('mpBar').style.width=state.mp/state.maxMp*100+'%';$('goldBag').textContent=state.gold.toLocaleString();$('dustBag').textContent=state.dust;$('potionBag').textContent=state.potions;$('potionCount').textContent=state.potions;$('mobilePotionCount').textContent=state.potions;$('mobileHp').textContent='HP '+Math.round(state.hp/state.maxHp*100)+'%';$('heroName').textContent=state.level>=50?'별빛의 '+(state.secondJob||state.firstJob||'모험가'):'새벽의 모험가';$('jobName').textContent=state.job;$('questProgress').textContent=`처치 ${Math.min(5,state.kills)} / 5`;if(state.kills>=5)$('questTitle').textContent='숲의 첫 수호자';const zi=zoneIndex(l);$('zoneIcon').textContent=zoneIcons[zi];$('zoneName').textContent=getZone();$('maplabel').textContent=getZone();$('zoneSub').textContent=['초심자의 사냥터 · 안전 지역','모래바람의 유적','고대 산맥의 관문','심해의 균열','얼음 왕관 성채','차원의 최후 전선'][zi];$('nearCount').textContent=`${state.seen.size} / 60`;drawMap();renderEnemies()}
function makeMonster(){const zi=zoneIndex(state.level),range=monsterData.filter(m=>Math.floor((m[2]-1)/30)===zi);const choice=range[Math.floor(Math.random()*range.length)]||monsterData[0];const lvl=Math.max(1,Math.min(200,choice[2]+Math.floor(Math.random()*5))),hp=choice[3]*(1+(lvl-choice[2])*.035);return{data:choice,lvl,x:.12+Math.random()*.76,y:.15+Math.random()*.73,hp,maxHp:hp,cool:Math.random()*2,hit:0}}
function ensureMonsters(){while(state.monsters.length<9)state.monsters.push(makeMonster())}
function renderEnemies(){const list=$('enemyList');if(!list)return;const seen=[...state.seen].slice(-6).reverse(),items=seen.length?seen.map(name=>monsterData.find(a=>a[1]===name)):monsterData.slice(0,5);list.innerHTML=items.map(m=>`<div class="enemy"><span class="ico">${m?.[0]||'❔'}</span><div><b>${m?.[1]||'???'}</b><small>경험치 +${m?.[4]||'?'} · HP ${m?.[3]||'?'}</small></div><span class="lvl">Lv.${m?.[2]||'?'}</span></div>`).join('')}
function addXP(n){if(state.level>=200)return;state.xp+=n;while(state.xp>=expNeed(state.level)&&state.level<200){state.xp-=expNeed(state.level);state.level++;state.hp=100+state.level*12;state.mp=60+state.level*4;toast(`레벨 업! Lv.${state.level} ✨`);if(state.level===50||state.level===150)setTimeout(()=>promotion(state.level===50?1:2),450)}if(state.level===200)state.xp=0;refresh()}
function promotion(stage){const choices=stage===1?[['🛡️','수호기사','방어와 생명력이 강한 기사'],['🏹','별궁수','빠르고 정확한 원거리 사냥꾼'],['🔮','성운술사','강력한 마법과 별빛 기술']]:[['⚔️','성검군주','빛을 가르는 전설의 검'],['🌠','천공추적자','유성과 함께하는 명사수'],['✨','대마도사','성운을 다루는 마법의 정점']];$('modal').innerHTML=`<div class="eyebrow">${stage===1?'LEVEL 50 · 1차 전직':'LEVEL 150 · 2차 전직'}</div><h2>${stage===1?'새로운 길을 선택하세요':'전설의 문이 열렸어요'}</h2><p>마음에 드는 직업을 선택해 주세요.</p>${choices.map(c=>`<button class="choice" data-job="${c[1]}"><b>${c[0]} ${c[1]}</b><br><span style="font-size:11px;color:#a8a9a8">${c[2]}</span></button>`).join('')}`;$('modalWrap').classList.add('open');$('modal').querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{state.job=b.dataset.job;if(stage===1)state.firstJob=b.dataset.job;else state.secondJob=b.dataset.job;state.hp=state.maxHp;state.mp=state.maxMp;$('modalWrap').classList.remove('open');toast(`${state.job}로 전직했습니다!`);refresh()})}
function strike(){if(state.paused)return;state.attackTimer=.22;const candidates=state.monsters.map((m,i)=>({m,i,d:Math.hypot((m.x-state.player.x)*W,(m.y-state.player.y)*H)})).filter(a=>a.d<Math.min(190,W*.4)).sort((a,b)=>a.d-b.d);if(!candidates.length){toast('몬스터가 가까이 없어요. 방향키로 다가가세요!');return}const{m,i}=candidates[0],base=18+state.level*3.2+(state.firstJob?35:0)+(state.secondJob?100:0);m.hp-=base*(.8+Math.random()*.5);m.hit=.24;state.mp=Math.min(state.maxMp,state.mp+2);if(m.hp<=0){state.kills++;state.gold+=Math.floor(m.data[4]*(.6+Math.random()*.8));state.dust+=Math.random()<.16?1:0;state.seen.add(m.data[1]);addXP(m.data[4]);state.monsters.splice(i,1);if(state.kills===5){state.gold+=100;state.potions++;toast('퀘스트 완료! +100 골드 · 물약 +1')}refresh()}else refresh()}
function heal(){if(state.mp<12){toast('마나가 부족해요!');return}if(state.hp>=state.maxHp){toast('생명력이 이미 가득해요');return}state.mp-=12;state.hp=Math.min(state.maxHp,state.hp+state.maxHp*.32);refresh();toast('회복의 빛! 생명력 회복')}
function potion(){if(state.potions<=0){toast('물약이 없어요!');return}state.potions--;state.hp=Math.min(state.maxHp,state.hp+state.maxHp*.55);refresh();toast('회복 물약을 사용했어요')}
$('attackBtn').onclick=strike;$('mobileAttack').onclick=strike;$('healBtn').onclick=heal;$('potionBtn').onclick=potion;$('mobilePotion').onclick=potion;

